STATUS_SR={"DRAFT":"Nacrt","READY_FOR_REVIEW":"Spremno za pregled","ISSUED":"Izdato","SENT":"Poslato","PAID":"Plaćeno","PARTIALLY_PAID":"Delimično plaćeno","OVERDUE":"Dospelo","DISPUTED":"Osporeno","VOID":"Stornirano"}

def status_sr(s): return STATUS_SR.get((s or "").upper(), s or "Nepoznato")
def money(v,c="RSD"):
    try: n=float(v or 0)
    except Exception: n=0
    return f"{n:,.2f}".replace(",","X").replace(".",",").replace("X",".")+f" {c or 'RSD'}"

def finance_footer():
    return """<section class='finance-footer no-print'><div class='finance-benefit'><i>🛡</i><span>Potpuna kontrola<br>nad finansijama</span></div><div class='finance-benefit'><i>📋</i><span>Jasni izveštaji<br>i pregled računa</span></div><div class='finance-benefit'><i>💰</i><span>Brža naplata<br>i manje kašnjenja</span></div><div class='finance-benefit'><i>🔒</i><span>Sigurnost podataka<br>i usklađenost</span></div></section>"""

def page(title, body):
    return HTMLResponse(f"""<!doctype html><html lang='sr'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{escape(title)}</title><style>{CSS}</style></head><body>{body}<script>document.querySelectorAll('.main').forEach(function(el){{if(!el.querySelector('.finance-footer')) el.insertAdjacentHTML('beforeend', `{finance_footer()}`);}});</script></body></html>""")

def sidebar(active="Fakture"):
    items=[("Kontrolna tabla","📊"),("Fakture","🧾"),("Uplate","💳"),("Izveštaji","📈"),("Partneri","🤝"),("Korisnici","👥"),("Podešavanja","⚙️")]
    links="".join([f"<a class='{ 'active' if label==active else '' }' href='#'><span>{icon}</span>{label}</a>" for label,icon in items])
    return f"""<aside class='side no-print'><div class='brand'><div class='logo'><img src='/admin-assets/brand/logo-mark.svg' alt='Sačuvaj Hranu'></div><div><div class='brand-title'>Sačuvaj<br><span>Hranu</span></div><div class='tag'>Uštedi novac. Sačuvaj obrok.</div></div></div><nav class='nav'>{links}<a href='#' style='margin-top:28px'><span>↩</span>Odjavi se</a></nav></aside>"""

